(()=>{'use strict';
const P=window.ProbePhysics,$=id=>document.getElementById(id),PI=Math.PI,TAU=2*PI,C=window.BookTheme.palette({gold:'#e4c389',cyan:'#7abdc4',muted:'#98aeae',line:'#293c45'}),key='galaxies-chapter-6-labs';
const s={fraction:.6,width:4,bin:2,pairSeed:1,infall:.6,sigma:0,progress:1,logMass:11.4,source:.3,sourceWidth:.09,kappa:.15,g:.2,angle:30,ell:5,cmbSeed:1};
const ranges={fraction:[0,1],width:[2,8],bin:[0,14],pairSeed:[1,9999],infall:[0,.8],sigma:[0,700],progress:[0,1],logMass:[10,12],source:[-1.8,1.8],sourceWidth:[.04,.3],kappa:[0,.4],g:[0,.4],angle:[0,90],ell:[2,100],cmbSeed:[1,9999]};
try{const v=JSON.parse(localStorage.getItem(key)||'{}');for(const k of Object.keys(ranges))if(typeof v[k]==='number'&&Number.isFinite(v[k]))s[k]=Math.max(ranges[k][0],Math.min(ranges[k][1],v[k]));for(const k of ['bin','pairSeed','ell','cmbSeed'])s[k]=Math.round(s[k]);}catch{}
const inputs={'pair-fraction':'fraction','pair-width':'width','pair-bin':'bin','rsd-infall':'infall','rsd-sigma':'sigma','rsd-progress':'progress','lens-mass':'logMass','lens-source':'source','lens-width':'sourceWidth','shear-kappa':'kappa','shear-g':'g','shear-angle':'angle','cmb-ell':'ell'};
for(const [id,k] of Object.entries(inputs))$(id).value=s[k];
function save(){try{localStorage.setItem(key,JSON.stringify(s));}catch{}}
const fmt=(n,d=3)=>(Math.abs(n)<.5*10**(-d)?0:n).toLocaleString('zh-CN',{minimumFractionDigits:d,maximumFractionDigits:d});
const sci=n=>Math.abs(n)>=10000||(n!==0&&Math.abs(n)<.001)?n.toExponential(2):fmt(n,3);
const running=new Map(),labels={'rsd-play':'演示坐标映射','lens-play':'扫描源的位置'};
function stop(id){const run=running.get(id);if(run)cancelAnimationFrame(run.frame);running.delete(id);$(id).textContent=labels[id];$(id).setAttribute('aria-pressed','false');save();}
function animate(id,start,end,set,render,duration=7000){const run={frame:0,last:-100},t0=performance.now();running.set(id,run);$(id).textContent='暂停';$(id).setAttribute('aria-pressed','true');function frame(now){const a=Math.min(1,(now-t0)/duration);set(start+(end-start)*a);if(now-run.last>48||a===1){render();run.last=now;}if(a<1)run.frame=requestAnimationFrame(frame);else{stop(id);$(id).textContent='重新播放';}}run.frame=requestAnimationFrame(frame);}
document.addEventListener('visibilitychange',()=>{if(document.hidden)for(const id of [...running.keys()])stop(id);});
function bind(id,render,animation){$(id).addEventListener('input',e=>{if(animation)stop(animation);s[inputs[id]]=+e.target.value;save();render();});}
function canvas(id){const c=$(id),rect=c.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);c.width=Math.round(rect.width*d);c.height=Math.round(rect.height*d);const ctx=c.getContext('2d');ctx.setTransform(d,0,0,d,0,0);return {c,ctx,w:rect.width,h:rect.height};}
const ticks=n=>n!==0&&(Math.abs(n)<.001||Math.abs(n)>=10000)?n.toExponential(0):d3.format('~g')(n);
function plot(id,x,y,xtitle,ytitle){return window.BookCharts.frame(id,{x,y,xLabel:xtitle,yLabel:ytitle});}
function curve(p,data,fx,fy,color=C.gold){const points=data.map(d=>({x:fx(d),y:fy(d)})),index=BookCharts.addSeries(p.node||p.svg.node(),points);return p.svg.append('path').datum(points).attr('data-plot-series',index).attr('d',d3.line().x(d=>p.x(d.x)).y(d=>p.y(d.y))).attr('fill','none').attr('stroke',color).attr('stroke-width',1.6);}
function selected(p,x,y,seriesIndex=0){BookCharts.includeSample(p.node||p.svg.node(),seriesIndex,x,y);p.svg.append('line').attr('x1',p.x(x)).attr('x2',p.x(x)).attr('y1',p.m.top).attr('y2',p.h-p.m.bottom).attr('stroke',C.muted).attr('stroke-dasharray','3 5');p.svg.append('circle').attr('cx',p.x(x)).attr('cy',p.y(y)).attr('data-model-point-series',seriesIndex).attr('data-model-point-x',x).attr('data-model-point-y',y).attr('r',4).attr('fill',C.gold);}
function panels(w,h){return w<500?[{x:0,y:0,w,h:h/2},{x:0,y:h/2,w,h:h/2}]:[{x:0,y:0,w:w/2,h},{x:w/2,y:0,w:w/2,h}];}
function title(ctx,p,text){ctx.fillStyle=C.muted;ctx.font='11px -apple-system,sans-serif';ctx.textAlign='left';ctx.fillText(text,p.x+14,p.y+23);}
let catalogue,pairData;function cachePairs(){catalogue=P.catalog({fraction:s.fraction,width:s.width,seed:s.pairSeed});pairData=P.pairs(catalogue);}cachePairs();
function pair(){const {c,ctx,w,h}=canvas('pair-canvas'),size=Math.min(w-54,h-54),ox=(w-size)/2,oy=18;ctx.strokeStyle=C.line;ctx.lineWidth=.8;for(let i=0;i<=4;i++){ctx.beginPath();ctx.moveTo(ox+size*i/4,oy);ctx.lineTo(ox+size*i/4,oy+size);ctx.moveTo(ox,oy+size*i/4);ctx.lineTo(ox+size,oy+size*i/4);ctx.stroke();}for(const p of catalogue){ctx.fillStyle=p.cluster?window.BookTheme.color('#e4c389d9'):window.BookTheme.color('#91b7b7a6');ctx.beginPath();ctx.arc(ox+p.x/100*size,oy+(1-p.y/100)*size,1.4,0,TAU);ctx.fill();}ctx.fillStyle=C.muted;ctx.font='10px -apple-system,sans-serif';ctx.textAlign='center';for(const a of [0,50,100])ctx.fillText(String(a),ox+a/100*size,oy+size+17);ctx.fillText('x（盒长单位）；周期边界',w/2,h-4);ctx.textAlign='left';const v=pairData[s.bin],p=plot('pair-chart',d3.scaleLinear().domain([0,30]),d3.scaleLinear().domain([-1,Math.max(1,d3.max(pairData,d=>d.xi)*1.12)]).nice(),'间距 r（盒长单位）','二维相关 ξ̂(r)');p.svg.append('line').attr('x1',p.x(0)).attr('x2',p.x(30)).attr('y1',p.y(0)).attr('y2',p.y(0)).attr('stroke',C.cyan).attr('stroke-dasharray','4 5');curve(p,pairData,d=>d.r,d=>d.xi);selected(p,v.r,v.xi);$('pair-fraction-value').textContent=fmt(s.fraction*100,0)+'%';$('pair-width-value').textContent=fmt(s.width,2);$('pair-bin-value').textContent=`${v.lo} ≤ r < ${v.hi}`;$('pair-bin').setAttribute('aria-valuetext',`间距 ${v.lo} 至 ${v.hi} 盒长单位`);$('pair-dd').textContent=fmt(v.dd,0);$('pair-rr').textContent=fmt(v.rr,1);$('pair-xi').textContent=fmt(v.xi);$('pair-result').textContent=`样本 ${s.pairSeed}：600 个点，共 179,700 个不同无序对；该分箱有 ${v.dd} 对。${v.xi>0?'这个间距的配对数量超过均匀参照。':'这个间距的配对数量低于或接近均匀参照。'}${s.fraction===0?'均匀抽样的单次计数也会波动。':''}`;c.setAttribute('aria-label',`第${s.pairSeed}份合成周期二维样本，600点，团簇比例${fmt(s.fraction*100,0)}%，宽度${fmt(s.width,2)}。`);}
bind('pair-fraction',()=>{cachePairs();pair();});bind('pair-width',()=>{cachePairs();pair();});bind('pair-bin',pair);$('pair-uniform').addEventListener('click',()=>{s.fraction=0;$('pair-fraction').value=0;save();cachePairs();pair();});$('pair-clustered').addEventListener('click',()=>{s.fraction=.6;$('pair-fraction').value=s.fraction;save();cachePairs();pair();});$('pair-resample').addEventListener('click',()=>{s.pairSeed=s.pairSeed%9999+1;save();cachePairs();pair();});
const cloud=P.velocityCloud();
function rsd(){const mapped=P.redshift(cloud,s.infall,s.sigma,s.progress),{c,ctx,w,h}=canvas('rsd-canvas');panels(w,h).forEach((p,i)=>{title(ctx,p,i===0?'真实空间：固定位置':'右图：含视向速度的坐标');const side=Math.min(p.w-56,p.h-75),cx=p.x+p.w/2,cy=p.y+p.h/2+8,scale=side/84;ctx.strokeStyle=C.line;ctx.lineWidth=.8;ctx.beginPath();ctx.moveTo(cx-side/2,cy);ctx.lineTo(cx+side/2,cy);ctx.moveTo(cx,cy-side/2);ctx.lineTo(cx,cy+side/2);ctx.stroke();ctx.fillStyle=C.muted;ctx.font='10px -apple-system,sans-serif';ctx.fillText('−42',cx+4,cy+side/2);ctx.fillText('42',cx+4,cy-side/2+9);ctx.fillText('视线 ∥',cx+7,cy-side/2-5);ctx.textAlign='center';ctx.fillText('x（Mpc）',cx+side/2-14,cy+17);ctx.fillText('两轴范围固定：±42 Mpc',cx,p.y+p.h-10);ctx.textAlign='left';ctx.save();ctx.beginPath();ctx.rect(cx-side/2,cy-side/2,side,side);ctx.clip();mapped.forEach(v=>{ctx.fillStyle=i===0?window.BookTheme.color('#91b7b7c0'):window.BookTheme.color('#e4c389c0');ctx.beginPath();ctx.arc(cx+v.x*scale,cy-(i===0?v.z:v.zObserved)*scale,1.65,0,TAU);ctx.fill();});ctx.restore();});const rms=field=>Math.sqrt(mapped.reduce((a,p)=>a+p[field]**2,0)/mapped.length),real=rms('z'),observed=rms('zObserved');$('rsd-infall-value').textContent=fmt(s.infall,2);$('rsd-sigma-value').textContent=fmt(s.sigma,0);$('rsd-progress-value').textContent=fmt(s.progress*100,0)+'%';$('rsd-real').textContent=fmt(real);$('rsd-observed').textContent=fmt(observed);$('rsd-result').textContent=`两图始终对应同一批 ${cloud.length} 个标记。映射进度 ${fmt(s.progress*100,0)}%；${s.sigma===0&&s.infall===0?'没有特有速度，左右位置相同。':s.sigma===0?'相干内流让视线坐标按 (1−进度×A) 缩短。':'随机视向速度会增加红移位置的散布；这不是实际空间中的拉伸。'}`;c.setAttribute('aria-label',`真实空间与红移坐标的300标记，内流强度${fmt(s.infall,2)}，随机速度${s.sigma}km/s，映射进度${fmt(s.progress*100,0)}%，视向RMS由${fmt(real)}变为${fmt(observed)}Mpc。`);}
bind('rsd-infall',rsd,'rsd-play');bind('rsd-sigma',rsd,'rsd-play');bind('rsd-progress',rsd,'rsd-play');document.querySelectorAll('[data-rsd]').forEach(b=>b.addEventListener('click',()=>{stop('rsd-play');s.infall=b.dataset.rsd==='infall'?.6:0;s.sigma=b.dataset.rsd==='random'?500:0;s.progress=1;for(const [id,k] of [['rsd-infall','infall'],['rsd-sigma','sigma'],['rsd-progress','progress']])$(id).value=s[k];save();rsd();}));$('rsd-play').addEventListener('click',()=>{if(running.has('rsd-play')){stop('rsd-play');return;}if(s.progress>=1-.00001)s.progress=0;animate('rsd-play',s.progress,1,v=>{s.progress=v;$('rsd-progress').value=v;},rsd);});
const tile=document.createElement('canvas');tile.width=240;tile.height=240;const tileCtx=tile.getContext('2d');
function lens(){const v=P.pointLens(10**s.logMass,s.source),{c,ctx,w,h}=canvas('lens-canvas');panels(w,h).forEach((p,index)=>{title(ctx,p,index===0?'源平面：未透镜的面亮度':'像平面：反向光线映射');const size=Math.min(p.w-44,p.h-74),ox=p.x+(p.w-size)/2,oy=p.y+36,img=tileCtx.createImageData(240,240);for(let y=0;y<240;y++)for(let x=0;x<240;x++){const tx=((x+.5)/240*2-1)*4.3,ty=(1-(y+.5)/240*2)*4.3,I=P.lensPixelIntensity(tx,ty,index===0?0:v.thetaE,s.source,s.sourceWidth,8.6/240),i=(y*240+x)*4;img.data[i]=9+(228-9)*I;img.data[i+1]=21+(195-21)*I;img.data[i+2]=29+(137-29)*I;img.data[i+3]=255;}tileCtx.putImageData(img,0,0);ctx.imageSmoothingEnabled=true;ctx.drawImage(tile,ox,oy,size,size);ctx.strokeStyle=C.line;ctx.strokeRect(ox,oy,size,size);const cx=ox+size/2,cy=oy+size/2,scale=size/8.6;if(index===1){ctx.strokeStyle=window.BookTheme.color('#7abdc470');ctx.setLineDash([3,6]);ctx.beginPath();ctx.arc(cx,cy,v.thetaE*scale,0,TAU);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=C.cyan;ctx.beginPath();ctx.arc(cx,cy,2,0,TAU);ctx.fill();}ctx.fillStyle=C.muted;ctx.font='10px -apple-system,sans-serif';ctx.textAlign='center';ctx.fillText('−4.3',ox,oy+size+16);ctx.fillText('4.3',ox+size,oy+size+16);ctx.fillText(index===0?'角秒 · 同一面亮度色标':'角秒 · 虚线为 θE',cx,p.y+p.h-9);ctx.textAlign='left';});$('lens-mass-value').textContent=(10**s.logMass).toExponential(2);$('lens-mass').setAttribute('aria-valuetext',(10**s.logMass).toExponential(2)+' 太阳质量');$('lens-source-value').textContent=fmt(s.source,2);$('lens-einstein').textContent=fmt(v.thetaE);$('lens-images-label').textContent=Math.abs(s.source)<1e-9?'环的轴向截面 ±θE（角秒）':'点像位置 θ+ / θ−（角秒）';$('lens-images').textContent=fmt(v.thetaPlus,2)+' / '+fmt(v.thetaMinus,2);$('lens-width-value').textContent=fmt(s.sourceWidth,3);$('lens-finite-mag').textContent=fmt(P.finiteMagnification(v.thetaE,s.source,s.sourceWidth));$('lens-mag').textContent=Number.isFinite(v.totalMagnification)?fmt(v.totalMagnification):'∞';$('lens-result').textContent=Math.abs(s.source)<1e-9?'源中心完全对齐。点源总放大率在理想极限发散；同一σ的有限高斯源放大率有限，形成有宽度的环。两幅图均按像素面积平均亮度；有限源读数由源面完整积分给出，不受画布±4.3″截断限制。':'源中心偏离光轴，两个点像的解析位置分别在透镜两侧；有限源图像可呈弧状；两幅图均按像素面积平均亮度；有限源读数与图像使用相同σ，但积分覆盖完整源面。透镜保持面亮度，增加的总通量来自更大的像面积。';c.setAttribute('aria-label',`点质量透镜，质量${(10**s.logMass).toExponential(2)}太阳质量，源位置${fmt(s.source,2)}角秒，Einstein半径${fmt(v.thetaE)}角秒。有限高斯源的逆向映射图像。`);}
bind('lens-mass',lens,'lens-play');bind('lens-source',lens,'lens-play');bind('lens-width',lens,'lens-play');$('lens-align').addEventListener('click',()=>{stop('lens-play');s.source=0;$('lens-source').value=0;save();lens();});$('lens-offset').addEventListener('click',()=>{stop('lens-play');s.source=.8;$('lens-source').value=s.source;save();lens();});$('lens-play').addEventListener('click',()=>{if(running.has('lens-play')){stop('lens-play');return;}s.source=-1.8;animate('lens-play',-1.8,1.8,v=>{s.source=v;$('lens-source').value=v;},lens,8000);});
function shear(){const v=P.weakLens(s.kappa,s.g,s.angle*PI/180),{c,ctx,w,h}=canvas('shear-canvas');panels(w,h).forEach((p,i)=>{title(ctx,p,i===0?'未透镜：单位半径小圆源':'局部像：同一坐标与面亮度');const cx=p.x+p.w/2,cy=p.y+p.h/2+8,R=Math.min(p.w-60,p.h-80)/6.4;ctx.strokeStyle=C.line;ctx.lineWidth=.8;ctx.beginPath();ctx.moveTo(cx-3*R,cy);ctx.lineTo(cx+3*R,cy);ctx.moveTo(cx,cy-3*R);ctx.lineTo(cx,cy+3*R);ctx.stroke();ctx.strokeStyle=window.BookTheme.color('#7abdc480');ctx.setLineDash([3,6]);ctx.beginPath();ctx.arc(cx,cy,R,0,TAU);ctx.stroke();ctx.setLineDash([]);ctx.save();ctx.translate(cx,cy);ctx.rotate(-s.angle*PI/180);ctx.fillStyle=window.BookTheme.color('#e4c38948');ctx.strokeStyle=C.gold;ctx.lineWidth=1.2;ctx.beginPath();ctx.ellipse(0,0,R*(i?v.major:1),R*(i?v.minor:1),0,0,TAU);ctx.fill();ctx.stroke();ctx.restore();ctx.fillStyle=C.muted;ctx.font='10px -apple-system,sans-serif';ctx.textAlign='center';ctx.fillText('虚线：原始半径 1；固定尺度',cx,p.y+p.h-12);ctx.textAlign='left';});$('shear-kappa-value').textContent=fmt(s.kappa,2);$('shear-g-value').textContent=fmt(s.g,2);$('shear-angle-value').textContent=fmt(s.angle,0)+'°';$('shear-gamma').textContent=fmt(v.gamma);$('shear-ratio').textContent=fmt(v.axisRatio);$('shear-mag').textContent=fmt(v.magnification);$('shear-result').textContent=`γ=${fmt(v.gamma)}，长半轴为源半径的 ${fmt(v.major)} 倍，短半轴为 ${fmt(v.minor)} 倍。${s.g===0?'没有剪切，像仍为圆形；κ可以改变整体大小。':'固定 g 时，改变 κ 不改变轴比，但会改变尺寸与面积放大率。'}`;c.setAttribute('aria-label',`圆源的局部透镜形变：会聚${fmt(s.kappa,2)}，约化剪切${fmt(s.g,2)}，长轴方向${fmt(s.angle,0)}度，轴比${fmt(v.axisRatio)}，面积放大率${fmt(v.magnification)}。`);}
bind('shear-kappa',shear);bind('shear-g',shear);bind('shear-angle',shear);$('shear-compare').addEventListener('click',()=>{s.kappa=s.kappa<.2?.35:.05;$('shear-kappa').value=s.kappa;save();shear();});$('shear-zero').addEventListener('click',()=>{s.kappa=0;s.g=0;$('shear-kappa').value=0;$('shear-g').value=0;save();shear();});
let cmbData=P.cmbSpectrum(s.cmbSeed);function cmb(){const v=cmbData[s.ell-2],p=plot('cmb-chart',d3.scaleLinear().domain([2,100]),d3.scaleLinear().domain([0,Math.max(2.2,d3.max(cmbData,d=>d.ratio)*1.1)]).nice(),'多极 ℓ','Ĉℓ / 理论 Cℓ');p.svg.append('path').datum(cmbData).attr('d',d3.area().x(d=>p.x(d.ell)).y0(d=>p.y(1-d.fractionalSigma)).y1(d=>p.y(1+d.fractionalSigma))).attr('fill',C.cyan).attr('fill-opacity',.18);p.svg.append('line').attr('x1',p.x(2)).attr('x2',p.x(100)).attr('y1',p.y(1)).attr('y2',p.y(1)).attr('stroke',C.cyan).attr('stroke-dasharray','4 5');curve(p,cmbData,d=>d.ell,d=>d.ratio);selected(p,v.ell,v.ratio);$('cmb-ell-value').textContent=String(s.ell);$('cmb-modes').textContent=v.modes;$('cmb-sigma').textContent=fmt(v.fractionalSigma*100,1)+'%';$('cmb-ratio').textContent=fmt(v.ratio);$('cmb-realization').textContent='假想天空 '+s.cmbSeed;$('cmb-result').textContent=`ℓ=${s.ell}，粗略角尺度约 ${fmt(180/s.ell,1)}°；${v.modes} 个独立实自由度给出 ${fmt(v.fractionalSigma*100,1)}% 的分数标准差。本次估计偏离均值 ${fmt((v.ratio-1)*100,1)}%，并不表示理论均值随抽样改变。`;}
bind('cmb-ell',cmb);$('cmb-resample').addEventListener('click',()=>{s.cmbSeed=s.cmbSeed%9999+1;save();cmbData=P.cmbSpectrum(s.cmbSeed);cmb();});
window.ProbeConcepts.forEach(item=>{const article=document.createElement('article');article.className='concept-reading';const h=document.createElement('h3');h.textContent=item.title;const body=document.createElement('p');body.textContent=item.body;const caveat=document.createElement('p');caveat.className='concept-caveat';caveat.textContent=item.caveat;const ref=document.createElement('small');ref.textContent=item.section;article.append(h,body,caveat,ref);$(item.target).append(article);});
window.ProbeQuizzes.forEach(item=>{const row=document.createElement('article');row.className='quiz-item';const h=document.createElement('h3');h.textContent=item.q;const options=document.createElement('div');options.className='quiz-options';const feedback=document.createElement('p');feedback.className='quiz-feedback';feedback.setAttribute('aria-live','polite');item.options.forEach((option,i)=>{const b=document.createElement('button');b.textContent=option;b.setAttribute('aria-pressed','false');b.addEventListener('click',()=>{options.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));feedback.textContent=(i===item.answer?'正确。':'再想一步。')+item.why;});options.append(b);});row.append(h,options,feedback);$('probe-quiz').append(row);});
function tutor(prompt){window.showTutor('我在学习Mo, van den Bosch & White (2010)《Galaxy Formation and Evolution》第6章。'+prompt+' 请逐步解释物理意义，核对单位和假设，区分教材结论、教学模型和补充推导；不要把合成样本当作观测数据。');}
$('tutor-open').addEventListener('click',()=>tutor('依据§6.1–6.7 pp.262–318，梳理位置、特有速度、引力透镜和CMB如何共同约束密度场，解释各自的选择效应与简并。'));
$('pair-question').addEventListener('click',()=>{const v=pairData[s.bin];tutor(`依据§6.1.2和§6.5.1 pp.264–266、284–285，二维周期盒L=100,N=600,团簇比例=${s.fraction},高斯宽度=${s.width},样本${s.pairSeed}；间距[${v.lo},${v.hi})，DD=${v.dd},RR=${fmt(v.rr,3)},ξ=${fmt(v.xi)}。RR是同N均匀样本的解析环带期望。请核算归一化，并解释这与三维球壳及真实巡天选择函数的区别。`);});
$('rsd-question').addEventListener('click',()=>tutor(`依据§6.2–6.3 pp.270–278，a=1,H0=70km/s/Mpc，固定300个高斯团簇标记，v∥=−A H0r∥+σv ε，A=${fmt(s.infall,2)},σv=${s.sigma}km/s，坐标映射进度${fmt(s.progress)}。请解释压扁和上帝手指的机制。本指定速度演示不是自洽坍缩，也未数值实现Kaiser线性场。`));
$('lens-question').addEventListener('click',()=>{const v=P.pointLens(10**s.logMass,s.source);tutor(`依据§6.6.2 pp.295–297及作者勘误，薄点质量透镜M=${(10**s.logMass).toExponential(3)}M☉，物理角径距离dL=1000,dS=1600,dLS=1000Mpc，β=${fmt(s.source,3)}角秒，θE=${fmt(v.thetaE)}角秒。请推导中心点像位置与放大率，解释对齐点源发散和有限高斯源σ=${s.sourceWidth}角秒图像的区别；请核对有限源积分放大率${P.finiteMagnification(v.thetaE,s.source,s.sourceWidth)}。`);});
$('shear-question').addEventListener('click',()=>tutor(`依据§6.6.1 pp.294–295，局部会聚κ=${fmt(s.kappa)},约化剪切g=${fmt(s.g)},γ=g(1−κ)=${fmt(s.g*(1-s.kappa))},长轴方向${s.angle}度。理想小圆源。请推导长短半轴、轴比与面积放大率；解释保持g但改变κ时哪些量不变，以及真实未知源形状带来的局限。`));
$('cmb-question').addEventListener('click',()=>tutor(`依据§6.7.1 pp.302–304与WMAP三年温度分析式34–35的教学延伸，理想全天高斯无噪声场，ℓ=${s.ell},自由度2ℓ+1=${2*s.ell+1},假想天空${s.cmbSeed},Ĉℓ/Cℓ=${fmt(cmbData[s.ell-2].ratio)}。请从χ²抽样推导分数标准差√[2/(2ℓ+1)]，解释宇宙方差以及均值±σ为何不等于低ℓ下严格68%区间。`));
let resize;window.addEventListener('resize',()=>{clearTimeout(resize);resize=setTimeout(()=>{pair();rsd();lens();shear();cmb();},120);});pair();rsd();lens();shear();cmb();
})();
